<?php
namespace App\Policies; use App\Domain\Tenancy\TenantContext; use App\Models\{PartnerStatement,User}; final class PartnerStatementPolicy{private function tenant(PartnerStatement$m):bool{return$m->tenant_id===app(TenantContext::class)->id();}public function viewAny(User$u):bool{return$u->memberships()->where('status','ACTIVE')->exists();}public function view(User$u,PartnerStatement$m):bool{return$this->tenant($m)&&$this->viewAny($u);}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,PartnerStatement$m):bool{return$this->view($u,$m)&&$m->status==='DRAFT';}public function delete(User$u,PartnerStatement$m):bool{return false;}}
